"""Register bounded primary passages actually inspected for T53.04."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];BASE=Path(__file__).resolve().parent
def write(path,value):path.write_text(json.dumps(value,indent=2)+'\n',encoding='utf-8',newline='\n')
def main():
 rows=[('R-LSI-INTEL','Intel SDM Volume3A','https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html','253668-060US September2016','build/legacy_concurrency/intel3a.pdf',[378,379,382,383,388,389,398,399,400,401,402,403,406,407],['10.5.4/10.5.4.1 printed10-16–17/PDF378–379: timer clock/ARAT qualifications, one-shot/periodic stop and TSC-deadline comparison','10.6.1 printed10-20–21/PDF382–383: ICR delivery status and physical destination','10.8.1 printed10-26–27/PDF388–389: destination/IRR and EOI removing ISR state','10.12.1–10.12.3 printed10-36–40/PDF398–402: CPUID.1:ECX.21, IA32_APIC_BASE, MSR map/reserved bits and device-store ordering','10.12.5 opening printed10-41/PDF403: mode transition constraints','10.12.8.1/10.12.9 printed10-44–45/PDF406–407: ID consistency and64-bit ICR without delivery-status bit'],'Historical bounded ISA passages, not current errata or every APIC mode. TSC-deadline comparison inspected but selected executed transfer is x2APIC.'),('R-LSI-C11','WG14 N1570 C11 draft','https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf','12April2011 committee draft','build/legacy_runtime_sources/n1570.pdf',[36,37,38,293],['5.1.2.4 paragraphs5–13/PDF36: synchronization operations, modification order and release/acquire reads-from relation','5.1.2.4 paragraphs16–18/PDF37: inter-thread and ordinary happens-before','5.1.2.4 paragraphs19–25/PDF38: visible side effects and data races','7.17.3 paragraphs1–4/PDF293: relaxed/acquire/release order operations'],'Actual C11 draft, not exact published C17 or C23. No consume, fence-rule or release-sequence edition-equivalence claim; this protocol directly acquires its matching release store.')]
 resources=[];documents=[]
 for rid,title,url,edition,path,pages,locators,limits in rows:
  digest=hashlib.sha256((ROOT/path).read_bytes()).hexdigest()
  resources.append({'id':rid,'title':title,'authors':['Primary document contributor named in title'],'url':url,'edition':edition,'locators':locators,'domains':['T53'],'kind':'standard' if rid.endswith('C11') else 'manual','access':'Actual selected primary PDF passages inspected','role':'primary','assignable':True,'reason':'Separate C publication, ISA notification, EOI and application completion.','prerequisites':['PR-T53-03','C17 objects and atomic operations'],'inspection':{'date':'2026-10-18','method':'Read actual PDF page text and adjacent listed normative clauses; exact private source hash retained.','scope':'; '.join(locators),'limits':limits,'local_sha256':digest}})
  documents.append({'path':path,'sha256':digest,'pdf_pages':pages})
 write(BASE/'resources.json',{'schema_version':1,'resources':resources,'reference_gaps':['Exact readable published C17 text unavailable; C11 draft distinction retained.','Current physical CPU errata and physical clock calibration not established.']})
 write(BASE/'source_access.json',{'schema_version':1,'date':'2026-10-18','actual_documents':documents,'scope':'Only listed passages actually read; primary texts remain private and are not redistributed.'})
 write(BASE/'research_gate.json',{'status':'passage-inspected','domains':['T53'],'inspection_kind':'Author source inspection, not independent human review','research_input_sha256':{p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in (BASE/'resources.json',BASE/'source_access.json')}})
 print(json.dumps({'resources':len(resources)}))
if __name__=='__main__':main()
